    if(action==='run-health-check'){openDrawer('Health check complete',`<span class="badge green"><span class="dot green"></span>All checks passed</span><div class="drawer-section"><div class="status-line"><span class="dot green"></span><div class="grow">Runtime host</div><strong>12 ms</strong></div><div class="status-line"><span class="dot green"></span><div class="grow">Artifact storage</div><strong>Synced</strong></div><div class="status-line"><span class="dot green"></span><div class="grow">Vector database</div><strong>8 ms</strong></div></div><p class="muted">Checked just now</p>`);return}
    if(action==='inspect-topology'){openDrawer('Infrastructure topology',`<div class="drawer-section"><h3>Request path</h3><p><strong>MRLC Gateway</strong> → Runtime Host → Artifacts + Vector DB</p></div><div class="kv"><span>Ingress</span><strong>12 ms · healthy</strong><span>Workers</span><strong>2 active</strong><span>Persistence</span><strong>Synced · 0 lag</strong></div>`);return}
    if(action==='open-activity-timeline'){openDrawer('Task activity timeline',`<div class="status-line"><div class="avatar small">E</div><div class="grow"><strong>Engineer updated proof</strong><div class="muted">Resolved type error · 21:34</div></div></div><div class="status-line"><div class="avatar small violet">V</div><div class="grow"><strong>Reviewer left feedback</strong><div class="muted">Invariant manifold definition · 19:12</div></div></div>`);return}
    if(action==='scenario-switcher'){openModal('Scenario',`<p class="muted">Switch the data state without changing the interface structure.</p><div class="command-results"><button class="command-result selected" data-action="select-scenario" data-scenario="normal"><span class="dot green"></span><div><strong>Normal operation</strong><div class="muted">Current · two active slots</div></div></button><button class="command-result" data-action="select-scenario" data-scenario="approval"><span class="dot amber"></span><div><strong>Approval bottleneck</strong><div class="muted">Five blocked tasks</div></div></button><button class="command-result" data-action="select-scenario" data-scenario="incident"><span class="dot red"></span><div><strong>Runtime incident</strong><div class="muted">Provider degraded and queue growing</div></div></button></div>`,'Apply scenario','apply-scenario');return}
    if(action==='select-scenario'){document.querySelectorAll('[data-action="select-scenario"]').forEach(x=>x.classList.remove('selected'));trigger.classList.add('selected');state.scenario=trigger.dataset.scenario;showToast('Scenario selected: '+trigger.textContent.trim());return}
    if(action==='apply-scenario'){if(state.scenario==='normal'){projects[0].status='Running';projects[0].attention=2;slots.forEach(slot=>slot.paused=false)}if(state.scenario==='approval'){projects[0].status='Blocked';projects[0].attention=5;if(!approvals.some(item=>item.title==='Blocked-task triage'))approvals.push({title:'Blocked-task triage',type:'Project decision',from:'Project Manager',risk:'Medium',project:'World Model Research',wait:6,why:'Five tasks are waiting on a shared scope decision.',effect:'Unblocks the next executable task set.',evidence:'Dependency map · resource forecast'})}if(state.scenario==='incident'){projects[0].status='Blocked';projects[0].attention=3;slots.forEach(slot=>slot.paused=true)}renderApprovals();renderCompute();closeSurfaces();showToast('Scenario applied: '+state.scenario);return}
    if(action==='pause-slot'){const id=document.getElementById('drawer').dataset.slotId||trigger.closest('.slot')?.querySelector('h2')?.textContent.replace('Slot ','');const slot=slots.find(item=>item.id===id);if(slot)slot.paused=!slot.paused;renderCompute();closeSurfaces();showToast(slot?.paused?'Slot paused':'Slot resumed');return}
    if(action==='release-slot'){const id=document.getElementById('drawer').dataset.slotId||trigger.closest('.slot')?.querySelector('h2')?.textContent.replace('Slot ','');const index=slots.findIndex(item=>item.id===id);if(index>=0)slots.splice(index,1);renderCompute();closeSurfaces();showToast('Slot released');return}
    if(action==='save-settings'){savedSettings=readSettings();applySettings(savedSettings);showToast('Settings saved');return}
    if(action==='reset-settings'){savedSettings={...defaultSettings};writeSettings(savedSettings);applySettings(savedSettings);showToast('Settings reset to project defaults');return}
    throw new Error('Unhandled action: '+action)
