  document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();handleAction('open-command',document.body)}if(e.key==='Escape')closeSurfaces()});
  function selectChannel(key){state.channel=key;document.querySelectorAll('.channel').forEach(x=>x.classList.toggle('active',x.dataset.channel===key));document.getElementById('channel-title').textContent=channels[key][0];document.getElementById('channel-subtitle').textContent=channels[key][1];document.getElementById('message-input').placeholder='Message '+channels[key][0].toLowerCase()+'…';renderMessages()}
