  function renderMessages(){const list=document.getElementById('message-list');list.innerHTML=messages[state.channel].map(m=>m[2]==='STAGE'?`<div class="card completion-card completion-${m[6]||'low'}"><div class="card-body"><div class="completion-medal">✓</div><div class="grow"><strong>${m[4]}</strong><div class="muted">Runtime verified · ${m[3]}</div><div class="inline-actions" style="margin-top:9px"><button class="btn" data-page="tasks">View task</button><button class="btn" data-action="browse-artifacts">View artifacts</button><button class="btn" data-action="view-milestone">Evidence</button></div></div></div></div>`:`<div class="message"><div class="avatar ${m[1]}">${m[0]}</div><div class="message-body"><div class="message-meta"><strong>${m[2]}</strong><time>${m[3]}</time><button class="btn push" data-action="message-menu">•••</button></div><p>${m[4]}</p>${m[5]?`<div class="attachments">${m[5].split('|').map(x=>`<button class="attachment" data-action="open-artifact">▱ ${x}</button>`).join('')}</div>`:''}</div></div>`).join('');list.scrollTop=list.scrollHeight}
