  function renderTasks(){let visibleTasks=tasks.map((task,index)=>({task,index})).filter(({task})=>(!state.taskQuery||`${task.title} ${task.assignee}`.toLowerCase().includes(state.taskQuery))&&(state.taskStatus==='All statuses'||task.status===state.taskStatus)&&(state.taskAssignee==='All roles'||task.assignee===state.taskAssignee)&&(state.taskEvidence==='Any evidence state'||task.evidence===state.taskEvidence));if(state.sortProgress)visibleTasks.sort((a,b)=>b.task.progress-a.task.progress||a.index-b.index);document.getElementById('task-table').innerHTML=visibleTasks.map(({task:t,index:i})=>`<tr class="task-row ${i===state.task?'selected':''}" data-task="${i}"><td class="${i<3?'indent':''}"><strong>${t.title}</strong></td><td>${t.assignee}</td><td><span class="badge ${t.status==='In progress'?'green':t.status==='Blocked'?'red':''}">${t.status}</span></td><td><div class="mini-progress">${t.progress}%<div class="progress"><span style="width:${t.progress}%"></span></div></div></td><td>${t.dep}</td></tr>`).join('');const progressSort=document.getElementById('progress-sort');progressSort.textContent=state.sortProgress?'Default order':'Sort by progress';progressSort.setAttribute('aria-pressed',String(state.sortProgress));document.querySelectorAll('[data-task]').forEach(r=>r.onclick=()=>{state.task=+r.dataset.task;renderTasks()});const t=tasks[state.task];const statusTone=t.status==='In progress'?'green':t.status==='Blocked'?'red':'';document.getElementById('task-detail').innerHTML=`<div class="card-head"><h2>Task details</h2><span class="badge ${statusTone} push">${t.status}</span></div><div class="card-body"><h2 class="task-detail-title">${t.title}</h2><p class="muted task-detail-description">${t.desc}</p><div class="kv"><span>Assignee</span><strong>${t.assignee}</strong><span>Reviewer</span><strong>Reviewer</strong><span>Due date</span><strong>May 16 · 2.1h</strong></div><h3>Acceptance criteria <span class="muted">4 / 5</span></h3><div class="criteria"><div class="criterion"><span class="check">✓</span>Precise definitions and assumptions</div><div class="criterion"><span class="check">✓</span>Core lemmas implemented</div><div class="criterion"><span class="check">✓</span>No critical verification errors</div><div class="criterion"><span class="check">✓</span>Machine-checked artifacts generated</div><div class="criterion"><span class="check open">✓</span>Reproducible evidence bundle attached</div></div><div class="action-row"><button class="btn amber" onclick="showToast('Review started')">Start review</button><button class="btn" data-action="open-artifact">Open artifact</button><button class="btn" data-action="open-evidence-chain">Evidence chain</button></div></div>`}
  function renderRoles(){const visibleRoles=roles.map((role,index)=>({role,index})).filter(({role:r})=>(!state.roleQuery||`${r.name} ${r.purpose} ${r.caps.join(' ')}`.toLowerCase().includes(state.roleQuery))&&(state.roleLifecycle==='Any lifecycle'||r.status===state.roleLifecycle)&&(state.roleCapability==='Any capability'||r.caps.includes(state.roleCapability))&&(state.roleModel==='Any model'||r.model===state.roleModel));document.getElementById('role-count').textContent=visibleRoles.length+' roles';document.getElementById('role-list').innerHTML=visibleRoles.map(({role:r,index:i})=>`<div class="role-row ${i===state.role?'selected':''}" data-role="${i}"><div class="role-cell"><div class="avatar small ${r.color}">${r.code}</div><div><strong>${r.name}</strong><div class="muted">${r.purpose.split('.')[0]}</div></div></div><span>${r.ver}</span><div class="chips">${r.caps.map(x=>`<span class="chip">${x}</span>`).join('')}</div><span>${r.model}</span><span class="badge ${r.status==='Active'?'green':r.status==='Parked'?'amber':''}">${r.status}</span></div>`).join('');document.querySelectorAll('[data-role]').forEach(r=>r.onclick=()=>{state.role=+r.dataset.role;renderRoles()});const r=roles[state.role];document.getElementById('role-detail').innerHTML=`<div class="card-head"><div class="avatar ${r.color}">${r.code}</div><div style="margin-left:10px"><h2>${r.name} <span class="badge">${r.ver}</span></h2><div class="muted">${r.caps.join(' · ')}</div></div><span class="badge ${r.status==='Active'?'green':r.status==='Parked'?'amber':''} push">${r.status}</span></div><div class="card-body"><div class="inline-actions" style="margin-bottom:14px"><button class="btn primary" data-action="message-role">Message role</button><button class="btn" data-action="edit-role">Edit</button><button class="btn" data-action="park-role">Park</button><button class="btn" data-action="archive-role">Archive</button></div><h3>Purpose</h3><p>${r.purpose}</p><div class="chips">${r.caps.map(x=>`<span class="chip">${x}</span>`).join('')}</div><div class="lifecycle"><div class="life">Draft</div><div class="life ${r.status==='Active'?'active':''}">Active</div><div class="life ${r.status==='Parked'?'active':''}">Parked</div><div class="life ${r.status==='Archived'?'active':''}">Archived</div></div><div class="permission-grid" style="margin-top:18px"><div class="permission"><strong>Granted permissions</strong><ul><li>Read project artifacts</li><li>Create draft artifacts</li><li>Run verification tasks</li><li>Use standard compute</li></ul></div><div class="permission"><strong>Grantable permissions</strong><ul><li>High-memory compute</li><li>External model access</li><li>Publish deliverables</li><li>Manage team members</li></ul></div></div></div>`}
  function renderApprovals(){if(!document.getElementById('approval-list')||!document.getElementById('approval-detail'))return;let visibleApprovals=approvals.map((approval,index)=>({approval,index})).filter(({approval:a})=>(state.approvalProject==='All projects'||a.project===state.approvalProject)&&(state.approvalRisk==='All risks'||a.risk===state.approvalRisk));visibleApprovals.sort((a,b)=>(state.sortApprovals?b.approval.wait-a.approval.wait:a.approval.wait-b.approval.wait));document.getElementById('pending-count').textContent=visibleApprovals.length+' pending';if(!visibleApprovals.some(item=>item.index===state.approval)&&visibleApprovals.length)state.approval=visibleApprovals[0].index;document.getElementById('approval-list').innerHTML=visibleApprovals.length?visibleApprovals.map(({approval:a,index:i})=>`<div class="approval-card ${i===state.approval?'selected':''}" data-approval="${i}"><div class="approval-card-head"><div class="approval-card-title"><strong>${escapeHTML(a.title)}</strong><div class="approval-meta">${escapeHTML(a.type)} · ${escapeHTML(a.project)}</div></div><span class="risk-badge risk-${a.risk.toLowerCase()}">${a.risk}</span></div><div class="risk"><span class="avatar small ${a.from==='Reviewer'?'violet':a.from==='Researcher'?'green':a.from==='Project Manager'?'amber':''}">${a.from.split(' ').map(x=>x[0]).join('').slice(0,2)}</span><small class="muted">Requested by <strong>${escapeHTML(a.from)}</strong></small></div></div>`).join(''):'<div class="card-body muted">No pending approvals match these filters.</div>';document.querySelectorAll('[data-approval]').forEach(x=>x.onclick=()=>selectApproval(+x.dataset.approval));if(visibleApprovals.length)renderApprovalDetail();else document.getElementById('approval-detail').innerHTML='<div class="card-body muted">Adjust the filters to inspect a pending decision.</div>'}
  function selectApproval(i){state.approval=i;renderApprovals()}
  function renderApprovalDetail(){const a=approvals[state.approval];if(!a)return;document.getElementById('approval-detail').innerHTML=`<div class="card-head approval-detail-head"><div><h2>${escapeHTML(a.title)}</h2><div class="muted">${escapeHTML(a.type)} · ${escapeHTML(a.project)}</div></div><span class="risk-badge risk-${a.risk.toLowerCase()} push">${a.risk} risk</span></div><div class="card-body approval-detail-body"><div class="approval-facts"><div class="approval-fact"><span>Requested by</span><strong>${escapeHTML(a.from)}</strong></div><div class="approval-fact"><span>Waiting</span><strong>${a.wait} minutes</strong></div></div><h3>Why this is needed</h3><p>${escapeHTML(a.why)}</p><div class="decision-box"><strong>Impact</strong><p class="muted">${escapeHTML(a.effect)}</p></div><div class="decision-box"><strong>Evidence</strong><p class="muted">${escapeHTML(a.evidence)}</p><button class="btn" data-action="open-approval-evidence" style="margin-top:9px">Inspect evidence</button></div><div class="action-row"><button class="btn primary" onclick="resolveApproval('Approved')">Approve</button><button class="btn" onclick="resolveApproval('Approved with reduced scope')">Reduce scope</button><button class="btn" onclick="resolveApproval('More information requested')">Request details</button><button class="btn" onclick="resolveApproval('Rejected')">Reject</button></div></div>`}
