  function renderCompute(){if(!document.getElementById('scheduler-preview'))return;document.getElementById('slot-grid').innerHTML=slots.length?slots.map(s=>`<div class="card slot"><div class="slot-top"><h2>Slot ${s.id}</h2><span class="badge ${s.paused?'amber':'green'}"><span class="dot ${s.paused?'amber':'green'}"></span>${s.paused?'Paused':'Active'}</span><span class="uptime">Lease ${s.lease}</span></div><div class="slot-grid"><div><div class="metric-label">Role</div><strong>${s.role}</strong><div class="muted">${s.task}</div></div><div><div class="metric-label">Model</div><strong>${s.model}</strong><div class="muted">200K context</div></div><div><div class="metric-label">Decode tok/s</div><div class="metric-value">${s.paused?'0':s.decode}</div></div><div><div class="metric-label">Prefill tok/s</div><div class="metric-value">${s.paused?'0':s.prefill}</div></div><div><div class="metric-label">Context usage</div><div class="metric-value">${s.context}</div></div><div><div class="metric-label">VRAM usage</div><div class="metric-value" style="font-size:20px">${s.vram}</div></div></div><svg class="slot-spark" viewBox="0 0 500 36"><path style="stroke:${s.color}" d="M0 27 L30 26 L55 29 L85 22 L115 25 L145 20 L175 22 L205 17 L235 21 L265 11 L295 19 L325 14 L355 18 L385 7 L415 15 L445 12 L500 17"/></svg><div class="slot-actions"><button class="btn" data-action="inspect-slot">◉ Inspect</button><button class="btn" data-action="pause-slot">${s.paused?'▶ Resume':'Ⅱ Pause'}</button><button class="btn" data-action="release-slot">■ Release</button></div></div>`).join(''):'<div class="card card-body muted">No active compute slots.</div>';document.getElementById('resource-grid').innerHTML=resources.map((r,i)=>`<div class="resource"><div class="summary-title"><span class="dot ${i<2||i>3?'green':'cyan'}"></span>${r[0]}</div><div class="muted">${r[1]}</div><div class="metric-value">${r[2]}</div><svg viewBox="0 0 130 28"><path d="M0 23L15 22L30 17L45 19L60 10L75 14L90 7L105 12L130 9"/></svg><small class="muted">${r[3]}</small></div>`).join('');document.getElementById('scheduler-preview').innerHTML=queue.map(q=>`<div class="list-item"><span class="badge">${q[0]}</span><div class="grow"><strong>${q[1]}</strong><small>${q[2]} · ${q[5]}</small></div><span class="risk-badge risk-${q[4].toLowerCase()}">${q[4]}</span></div>`).join('');document.getElementById('scheduler-table').innerHTML=queue.map(q=>`<tr>${q.map((x,i)=>`<td>${i===4?`<span class="risk-badge risk-${x.toLowerCase()}">${x}</span>`:x}</td>`).join('')}</tr>`).join('')}
